17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        validateRequiredFields(ownerFieldsDto);
106	        normalizeTelephone(ownerFieldsDto);
107	        rejectDuplicateTelephone(ownerFieldsDto);
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        this.clinicService.saveOwner(owner);
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        headers.setLocation(UriComponentsBuilder.newInstance()
113	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
114	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
120	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
121	        if (currentOwner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        currentOwner.setAddress(ownerFieldsDto.getAddress());
125	        currentOwner.setCity(ownerFieldsDto.getCity());
126	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
127	        currentOwner.setLastName(ownerFieldsDto.getLastName());
128	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
129	        this.clinicService.saveOwner(currentOwner);
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Transactional
135	    @Override
136	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        this.clinicService.deleteOwner(owner);
142	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Pet pet = petMapper.toPet(petFieldsDto);
154	        owner.setId(ownerId);
155	        pet.setOwner(owner);
156	        pet.getType().setName(null);
157	        this.clinicService.savePet(pet);
158	        PetDto petDto = petMapper.toPetDto(pet);
159	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
160	            .buildAndExpand(pet.getId()).toUri());
161	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
167	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
168	        if (currentOwner != null) {
169	            Pet currentPet = this.clinicService.findPetById(petId);
170	            if (currentPet != null) {
171	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
172	                currentPet.setName(petFieldsDto.getName());
173	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
174	                this.clinicService.savePet(currentPet);
175	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	            }
177	        }
178	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
184	        HttpHeaders headers = new HttpHeaders();
185	        Visit visit = visitMapper.toVisit(visitFieldsDto);
186	        Pet pet = new Pet();
187	        pet.setId(petId);
188	        visit.setPet(pet);
189	        this.clinicService.saveVisit(visit);
190	        VisitDto visitDto = visitMapper.toVisitDto(visit);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
192	            .buildAndExpand(visit.getId()).toUri());
193	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
194	    }
195	
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner != null) {
202	            Pet pet = owner.getPet(petId);
203	            if (pet != null) {
204	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    /**
211	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
212	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
213	     * does not catch). The names of all offending fields are collected so the caller receives a
214	     * 400 response whose {@code errors} array lists each one.
215	     */
216	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
217	        List<String> missingFields = new ArrayList<>();
218	        if (isBlank(ownerFieldsDto.getFirstName())) {
219	            missingFields.add("firstName");
220	        }
221	        if (isBlank(ownerFieldsDto.getLastName())) {
222	            missingFields.add("lastName");
223	        }
224	        if (isBlank(ownerFieldsDto.getAddress())) {
225	            missingFields.add("address");
226	        }
227	        if (isBlank(ownerFieldsDto.getCity())) {
228	            missingFields.add("city");
229	        }
230	        if (isBlank(ownerFieldsDto.getTelephone())) {
231	            missingFields.add("telephone");
232	        }
233	        if (!missingFields.isEmpty()) {
234	            throw new InvalidOwnerFieldsException(missingFields);
235	        }
236	    }
237	
238	    private static boolean isBlank(String value) {
239	        return value == null || value.trim().isEmpty();
240	    }
241	
242	    /**
243	     * Normalizes an owner's {@code telephone} on create by removing every non-digit character and
244	     * requiring exactly ten digits to remain. The stripped, 10-digit value is written back onto the
245	     * request so it is what gets stored and returned. Any value that does not reduce to exactly ten
246	     * digits is rejected with a 400 response whose {@code errors} array names {@code telephone}.
247	     */
248	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
249	        String telephone = ownerFieldsDto.getTelephone();
250	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
251	        if (digits.length() != 10) {
252	            throw new InvalidOwnerFieldsException(List.of("telephone"));
253	        }
254	        ownerFieldsDto.setTelephone(digits);
255	    }
256	
257	    /**
258	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
259	     * The incoming value has already been reduced to its 10-digit normal form by
260	     * {@link #normalizeTelephone}; each existing owner's stored telephone is normalized the same
261	     * way (stripping non-digit characters) before comparison so differing input formats still
262	     * collide. A match results in a 409 response naming {@code telephone}.
263	     */
264	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
265	        String telephone = ownerFieldsDto.getTelephone();
266	        for (Owner existing : this.clinicService.findAllOwners()) {
267	            if (telephone.equals(normalizeDigits(existing.getTelephone()))) {
268	                throw new DuplicateOwnerTelephoneException(telephone);
269	            }
270	        }
271	    }
272	
273	    private static String normalizeDigits(String telephone) {
274	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
275	    }
276	}
